<script setup lang="ts">
import {fitLatticeToPrint,printBridgeWarning} from '../services/latticePrintSettings'
import {isSpatialPattern} from '../services/solidLightening'
import {inspectPolygonMesh} from '../services/geometry/polygon'
import GcodePanel from './GcodePanel.vue'
import {MAX_WORKSPACE_SOURCE_LENGTH,workspaceSourceByteLength} from '../services/workspaceDocument'
import {solidTopology,facePlane} from '../services/directSolidTools'
import {resolveSketchSupport} from '../services/mainSketchAssociation'
import {jointOptions,saveCadJoint,readCadJoints,removeCadJoints} from '../services/cadJoints'
import {exportFacetedStep,importFacetedStep} from '../services/cadStep'
import {exportRetainedStepForWorkbench,importStepForWorkbench,retainedStepSession} from '../services/cadStepRouting'
import {loadProjectStepModel,saveProjectStepModel} from '../services/cadStepIndexedDb'
import {cadDrawing,downloadCad} from '../services/cadDrawing'
import {ref,computed,watch,onUnmounted,defineAsyncComponent} from 'vue'
import type {MeshData} from '../core/mesh'
import type {PickHit} from '../services/rendererContracts'
import {sceneBody,previewMeshes} from '../services/mainModeling'
import {patchMainSource} from '../services/mainSourceEditing'
import {computeCadOperation,computeCadInspection,cancelMainSolid} from '../services/mainSolidWorker'
import {storageKeys,storageGet,storageSet} from '../services/safeStorage'
import {parseDirectDocument,type DirectSketch,type DirectDocument} from '../services/directModeling'
import type {CadOptions,CadAction} from '../services/cadWorkbench'
const NominalTrussPanel=defineAsyncComponent(()=>import('./NominalTrussPanel.vue'))
const props=defineProps<{meshes:MeshData[];selection:number[];hit:PickHit|null;source:string;ready:boolean;locale:string;initialAction?:CadAction;externalPreviewEpoch?:number}>()
const emit=defineEmits<{apply:[source:string];preview:[meshes:MeshData[]|null];close:[]}>()
const label=(a:string,b:string)=>props.locale==='ru'?a:b
const actions:[CadAction,string,string][]=[['lighten','Облегчение / каркас','Lightening / lattice'],['texture','Текстура поверхности','Surface texture'],['union','Объединить','Union'],['difference','Вычесть','Difference'],['intersection','Пересечь','Intersection'],['loft','Loft — между профилями','Loft'],['sweep','Sweep — вдоль пути','Sweep'],['mirror','Зеркало','Mirror'],['pattern','Массив тел','Body pattern'],['align','Выровнять','Align'],['distribute','Распределить','Distribute'],['resize','Габариты','Dimensions'],['draft','Уклон','Draft'],['hole','Отверстие','Hole'],['thread','Резьба','Thread'],['joint','Соединение','Joint']]
const o=ref<CadOptions>({action:props.initialAction??'union',lightening:{pattern:'web',axis:'z',cell:8,rib:1.35,rim:2,bottom:.6,top:0,seed:42,jitter:.7,lineWidth:.45,perimeters:3,skin:0,step:1.2,openTop:false,diagonals:true,wallDepth:0,keepCore:false},texture:{pattern:'ribs',pitch:6,height:.4,angle:0,seed:42,detail:3,invert:false,origin:[0,0,0],u:[1,0,0],v:[0,1,0]},ids:[],sketches:[],axis:[0,0,1],origin:[0,0,0],amount:10,count:5,width:6,height:2,depth:10,pitch:1,secondary:10,mode:'min',pathId:'',profileIds:[]})
const sketches=ref<DirectSketch[]>([]),error=ref(''),busy=ref(false),info=ref('')
const jointMin=ref(-180),jointMax=ref(180)
function loadJoint(){const j=readCadJoints(props.source).find(j=>j.parent===props.selection[0]&&j.child===props.selection[1]);if(j){o.value.axis=[...j.axis] as [number,number,number];o.value.origin=[...j.origin] as [number,number,number];o.value.mode=j.kind;o.value.amount=j.position;jointMin.value=j.min;jointMax.value=j.max}}
const spatialMode=computed(()=>isSpatialPattern(o.value.lightening?.pattern))
watch(()=>o.value.lightening?.pattern,pattern=>{if(isSpatialPattern(pattern)&&o.value.lightening){Object.assign(o.value.lightening,{cell:10,rib:3.2,step:1.2,skin:pattern==='bone'?2.4:0,openTop:pattern==='bone',jitter:pattern==='bone'?.8:0})}})
const printSettings=ref({nozzle:.4,layer:.2,lines:3,skinLayers:3,maxBridge:10,openTop:true})
const limitOpening=ref(false)
const bridgeWarning=computed(()=>{try{return o.value.lightening?printBridgeWarning(o.value.lightening,printSettings.value):false}catch{return false}})
function fitPrint(){try{if(o.value.lightening)o.value.lightening=fitLatticeToPrint(o.value.lightening,printSettings.value,limitOpening.value)}catch(e){error.value=String(e)}}
const textureFace=ref(false)
watch(textureFace,cancel)
const sectionZ=ref(0)
function stepExport(){try{downloadCad(exportFacetedStep(chosenBodies()),'application/step','model.step')}catch(e){error.value=String(e)}}
async function stepImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(!props.ready)throw Error('Build the current source first.');if(file.size>20_000_000)throw Error('STEP file exceeds 20 MB.');const bodies=importFacetedStep(await file.text());emit('apply',patchMainSource(props.source,props.meshes,{version:1,sketches:[],bodies:[...props.meshes.map(sceneBody),...bodies]}))}catch(e){error.value=String(e)}finally{input.value=''}}
async function retainedStepImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>16*1024*1024)throw Error('Retained STEP exceeds 16 MiB.');const result=importStepForWorkbench(await file.text());if(result.retainedModel){await saveProjectStepModel(result.retainedModel,result.report,result.retainedDocument);try{retainedStepSession.set(result.retainedModel,result.report,result.retainedDocument)}catch{/* IndexedDB remains authoritative. */}}info.value=result.retainedModel?`${result.report.route}; ${result.report.occurrenceIdentities.length} occurrence(s); authoritative model saved in project IndexedDB. AP242 semantics: ${result.report.semanticConformance.status}. Metadata loss: ${result.report.metadataLoss.join(', ')||'none'}; external refs: ${result.report.externalReferences.join(', ')||'none'}`:`${result.report.route}; imported as explicit faceted geometry; no B-rep or semantic relabeling.`;emit('apply',patchMainSource(props.source,props.meshes,{version:1,sketches:[],bodies:[...props.meshes.map(sceneBody),...result.bodies],interchange:{step:result.report}}))}catch(e){error.value=String(e)}finally{input.value=''}}
async function retainedStepExport(){try{const stored=await loadProjectStepModel();const model=stored?.model??retainedStepSession.get();if(!model)throw Error('No retained AP242 model is loaded. Mesh edits cannot be promoted back to retained topology.');const result=exportRetainedStepForWorkbench(model,stored?.document??retainedStepSession.document());downloadCad(result.text,'application/step','retained-model.step');info.value=`${result.certificate.capability}; retained graph preserved`}catch(e){error.value=String(e)}}
const chosenBodies=()=>props.selection.map(i=>retainedStepSession.body(sceneBody(props.meshes[i],i)))
function drawing(format:'svg'|'pdf'){try{const d=cadDrawing(chosenBodies(),sectionZ.value);downloadCad(d[format],format==='svg'?'image/svg+xml':'application/pdf','drawing.'+format)}catch(e){error.value=String(e)}}
async function inspection(){const ticket=++version;busy.value=true;error.value='';try{const report=await computeCadInspection(chosenBodies());if(ticket===version)info.value=report.map(p=>`${p.a} / ${p.b}: ${p.overlapMm3.toFixed(3)} mm³; gap ${p.gapMm.toFixed(3)} mm`).join('\n')}catch(e){if(ticket===version)error.value=String(e)}finally{if(ticket===version)busy.value=false}}
let version=0
const previewEpoch=ref(0)
function fieldPreview(meshes:MeshData[]|null){if(meshes){version++;cancelMainSolid();busy.value=false}emit('preview',meshes)}
function refresh(){const items=storageKeys('scad-main-sketches-v1:').flatMap(key=>{try{const anchor=JSON.parse(key.slice('scad-main-sketches-v1:'.length));if(anchor.entity)resolveSketchSupport(props.meshes,anchor);return parseDirectDocument(storageGet(key)??'').sketches}catch{return []}});sketches.value=[...new Map(items.map(s=>[s.id,s])).values()]}
refresh()
const selectionLabel=computed(()=>props.selection.map(i=>i+1).join(' → '))
function cancel(){version++;previewEpoch.value++;cancelMainSolid();busy.value=false;emit('preview',null)}
watch(()=>props.externalPreviewEpoch,cancel,{flush:'sync'})
watch(()=>o.value.action,a=>{o.value.mode=a==='mirror'?'copy':a==='hole'?'plain':a==='thread'?'internal':a==='joint'?'revolute':'min'});
watch(()=>props.source,cancel);watch(()=>props.selection,cancel,{deep:true});watch([jointMin,jointMax],cancel);watch(o,()=>{cancel();error.value='';info.value=''},{deep:true});onUnmounted(cancel)
function picked(){if(props.hit){o.value.origin=[...props.hit.point];o.value.axis=props.hit.normal.map(v=>-v) as [number,number,number]}}
async function calculate(apply=false){
 previewEpoch.value++
 error.value='';if(!props.ready){error.value=label('Сначала соберите текущий код','Build the current source first');return}
 const ticket=++version;busy.value=true
 try{
  const before:DirectDocument={version:1,sketches:[],bodies:props.meshes.map(sceneBody)},options=JSON.parse(JSON.stringify({...o.value,ids:props.selection.map(String),sketches:sketches.value}))
  if(options.action==='texture'&&textureFace.value){const hit=props.hit;if(!hit||props.selection.length!==1||hit.meshIndex!==props.selection[0])throw Error('Pick a face on the selected body.');const b=before.bodies[hit.meshIndex],topology=solidTopology(b.mesh),face=topology.faces.find(f=>f.triangles.includes(hit.triangleIndex));if(!face)throw Error('Pick a planar face.');const plane=facePlane(b,face);options.texture={...options.texture,...plane,triangles:face.triangles}}
  const request=options.action==='joint'?jointOptions(props.source,before.bodies,options,jointMin.value,jointMax.value):options
  const d=await computeCadOperation(before,request);if(ticket!==version)return
  if(options.action==='lighten'){const volume=(b:typeof d.bodies)=>b.filter(b=>options.ids.includes(b.id)).reduce((s,b)=>s+inspectPolygonMesh(b.mesh).signedVolumeMm3,0),old=volume(before.bodies),next=volume(d.bodies);info.value=label('Уменьшение объёма: ','Volume reduction: ')+(100*(old-next)/old).toFixed(1)+'% · '+(old/1000).toFixed(2)+' → '+(next/1000).toFixed(2)+' cm³'}
  if(apply){emit('preview',null);const retained=d.bodies.find(body=>body.brep)?.brep;if(retained)retainedStepSession.set(retained);const source=patchMainSource(props.source,props.meshes,d);if(workspaceSourceByteLength(source)>MAX_WORKSPACE_SOURCE_LENGTH)throw Error(label('Результат превышает лимит исходника. Увеличьте размер ячеек / шаг или уменьшите детализацию.','Result exceeds source size limit. Increase cell size / pitch or reduce detail.'));emit('apply',options.action==='joint'?saveCadJoint(source,d.bodies,options,jointMin.value,jointMax.value):source);storageSet('scad-cad-last-operation',JSON.stringify(o.value))}else emit('preview',previewMeshes(d))
 }catch(e){if(e instanceof Error&&e.name==='AbortError')return;error.value=e instanceof Error?e.message:String(e)}finally{if(ticket===version)busy.value=false}
}
</script>
<template><aside class="cad-workbench" @keydown.stop><header><strong>{{ label('Операции CAD','CAD operations') }}</strong><button @click="cancel();emit('close')">×</button></header>
 <label>{{ label('Операция','Operation') }}<select v-model="o.action"><option v-for="a in actions" :key="a[0]" :value="a[0]">{{ label(a[1],a[2]) }}</option></select></label><p>{{ label('Порядок тел','Body order') }}: {{ selectionLabel || '—' }}</p>
 <template v-if="o.action==='lighten'&&o.lightening"><details><summary>{{ label('Настройки FDM-печати','FDM print settings') }}</summary><label>{{ label('Сопло, мм','Nozzle, mm') }}<select v-model.number="printSettings.nozzle"><option :value="0.25">0.25</option><option :value="0.4">0.4</option><option :value="0.6">0.6</option><option :value="0.8">0.8</option></select></label><label>{{ label('Высота слоя, мм','Layer height, mm') }}<input v-model.number="printSettings.layer" type="number" min="0.05" step="0.05"></label><label>{{ label('Минимум линий в стенке','Minimum wall lines') }}<input v-model.number="printSettings.lines" type="number" min="1" max="8"></label><label>{{ label('Минимум слоёв дна / крышки','Minimum floor / roof layers') }}<input v-model.number="printSettings.skinLayers" type="number" min="0" step="1"></label><label>{{ label('Допустимый мост, мм (из теста принтера)','Bridge limit, mm (printer test)') }}<input v-model.number="printSettings.maxBridge" type="number" min="1" step="1"></label><label><input v-model="printSettings.openTop" type="checkbox">{{ label('Открытый верх','Open top') }}</label><label><input v-model="limitOpening" type="checkbox">{{ label('Ограничить номинальный проём','Limit nominal opening') }}</label><button @click="fitPrint">{{ label('Подогнать геометрию под печать','Fit geometry to print settings') }}</button><p v-if="bridgeWarning">{{ label('Размер проёма превышает заданный мост. Уменьшите ячейку или используйте поддержки.','Opening exceeds the bridge limit. Reduce cell size or use supports.') }}</p><p>{{ label('Подгоняет толщины под линии и слои. Для сквозных ячеек выбирает Z. Сопло задаёт начальную ширину линии 112.5%; её можно изменить ниже. Мост оценивается по размеру ячейки, без анализа траекторий. Проверяйте результат в слайсере.','Fits thicknesses to lines and layers; sets Z for channels. Nozzle sets an initial 112.5% line width, editable below. Bridge estimate uses cell size, not toolpaths. Inspect in a slicer.') }}</p></details><label>{{ label('Структура','Structure') }}<select v-model="o.lightening.pattern"><option value="bone">{{ label('Кость — объёмная пористость','Bone — organic porosity') }}</option><option value="spatial">{{ label('3D узлы и стержни','3D nodes and struts') }}</option><option value="bcc">{{ label('ОЦК (BCC)','Body-centered cubic (BCC)') }}</option><option value="octet">{{ label('Октет','Octet') }}</option><option value="grid">{{ label('Прямоугольная сетка','Grid') }}</option><option value="isogrid">{{ label('Изогрид','Isogrid') }}</option><option value="triangles">{{ label('Диагональный каркас','Diagonal skeleton') }}</option><option value="honeycomb">{{ label('Соты','Honeycomb') }}</option><option value="web">{{ label('Случайная паутина','Random web') }}</option></select></label><label v-if="!spatialMode">{{ label('Ось сквозных ячеек','Channel axis') }}<select v-model="o.lightening.axis"><option>x</option><option>y</option><option>z</option></select></label><label v-for="field in (spatialMode?[['cell','Ячейка','Cell'],['rib','Диаметр стержня','Strut diameter'],['lineWidth','Ширина линии печати','Extrusion width']]:[['cell','Ячейка','Cell'],['rib','Перемычка','Rib'],['rim','Рамка по габаритам','Bounding frame'],['bottom','Нижняя сплошная кожа','Bottom skin'],['top','Верхняя сплошная кожа','Top skin'],['lineWidth','Ширина линии печати','Extrusion width']])" :key="field[0]">{{ label(field[1],field[2]) }}, mm <input v-model.number="o.lightening[field[0] as 'cell'|'rib'|'rim'|'bottom'|'top'|'lineWidth']" type="number" min="0" step="0.1"></label><label>{{ label('Линий в перемычке','Lines per rib') }}<input v-model.number="o.lightening.perimeters" type="number" min="1" max="8"></label><button @click="o.lightening.rib=Math.ceil(o.lightening.rib/o.lightening.lineWidth)*o.lightening.lineWidth">{{ label('Округлить под линии печати','Round to extrusion lines') }}</button><template v-if="o.lightening.pattern==='web'||o.lightening.pattern==='bone'||o.lightening.pattern==='spatial'"><label>Seed <input v-model.number="o.lightening.seed" type="number"></label><button @click="o.lightening.seed++">{{ label('Другой вариант','Next variation') }}</button><label>{{ label('Случайность','Randomness') }}<input v-model.number="o.lightening.jitter" type="range" min="0" max="1" step="0.05"></label></template><template v-if="spatialMode"><label>{{ label('Область сетки','Lattice region') }}<select :value="(o.lightening.wallDepth??0)>0?'walls':'volume'" @change="o.lightening.wallDepth=($event.target as HTMLSelectElement).value==='walls'?3.6:0"><option value="volume">{{ label('Весь объём','Whole volume') }}</option><option value="walls">{{ label('Только стенки','Walls only') }}</option></select></label><template v-if="(o.lightening.wallDepth??0)>0"><label>{{ label('Глубина скелетной стенки, мм','Skeletal wall depth, mm') }}<input v-model.number="o.lightening.wallDepth" type="number" min="0.1" step="0.2"></label><label>{{ label('Середина тела','Body interior') }}<select v-model="o.lightening.keepCore"><option :value="false">{{ label('Пустая','Hollow') }}</option><option :value="true">{{ label('Сплошная сердцевина','Solid core') }}</option></select></label><p>{{ label('Сетка ограничена слоем у всех поверхностей, включая дно и верх. Для открытых ячеек установите наружную оболочку 0.','Lattice is restricted to a surface layer, including floor and roof. Set outer skin to 0 for open cells.') }}</p></template><label>{{ label('Наружная оболочка, мм','Outer skin, mm') }}<input v-model.number="o.lightening.skin" type="number" min="0" step="0.2"></label><label>{{ label('Шаг расчёта, мм','Sampling step, mm') }}<input v-model.number="o.lightening.step" type="number" min="0.1" step="0.1"></label><label><input v-model="o.lightening.openTop" type="checkbox">{{ label('Открыть оболочку сверху (+Z)','Open skin on top (+Z)') }}</label><label v-if="o.lightening.pattern==='spatial'"><input v-model="o.lightening.diagonals" type="checkbox">{{ label('Диагональные связи','Diagonal connections') }}</label><p>{{ label('Настоящая пространственная сеть. Кость — нерегулярные стержни со сглаженными узлами. Геометрия приближённая; прочность и печать без поддержек не гарантируются.','True spatial network. Bone uses irregular blended struts. Geometry is approximate; strength and support-free printing are not guaranteed.') }}</p></template><p v-else>{{ label('Ячейки идут вдоль выбранной оси. Для вертикальных каналов при печати выбирайте Z. Верхняя кожа образует мосты; проверяйте их в слайсере. Это геометрическое облегчение, без расчёта прочности.','Cells follow the selected axis. Use Z for vertical print channels. Top skin introduces bridges; inspect them in your slicer. This is geometric lightening, without structural analysis.') }}</p></template>
 <template v-if="o.action==='texture'&&o.texture"><label>{{ label('Рисунок','Pattern') }}<select v-model="o.texture.pattern"><option value="ribs">{{ label('Рёбра','Ribs') }}</option><option value="grooves">{{ label('Насечки','Grooves') }}</option><option value="knurl">{{ label('Ромбовая накатка','Diamond knurl') }}</option><option value="fuzzy">Fuzzy skin</option><option value="dimples">{{ label('Лунки','Dimples') }}</option><option value="waves">{{ label('Волны','Waves') }}</option></select></label><label><input v-model="textureFace" type="checkbox">{{ label('Только выбранная плоская грань','Picked planar face only') }}</label><label>{{ label('Шаг, мм','Pitch, mm') }}<input v-model.number="o.texture.pitch" type="number" min="0.1" step="0.5"></label><label>{{ label('Высота / глубина, мм','Height / depth, mm') }}<input v-model.number="o.texture.height" type="number" min="0.01" step="0.1"></label><label>{{ label('Угол, °','Angle, °') }}<input v-model.number="o.texture.angle" type="number" step="15"></label><label>{{ label('Детализация','Detail') }}<input v-model.number="o.texture.detail" type="number" min="3" max="8"></label><label v-if="o.texture.pattern==='fuzzy'">Seed<input v-model.number="o.texture.seed" type="number" step="1"></label><label><input v-model="o.texture.invert" type="checkbox">{{ label('Инвертировать рельеф','Invert relief') }}</label><p>{{ label('Настоящий рельеф для экспорта STL. Высота ≤ шага/4. На грани края остаются гладкими. Fuzzy skin меняет геометрию, а не траекторию печати.','Exportable geometry. Height ≤ pitch/4. Face borders stay smooth. Fuzzy skin changes geometry, not print toolpaths.') }}</p></template>
 <template v-if="['loft','sweep','pattern'].includes(o.action)"><button @click="refresh">{{ label('Обновить эскизы','Refresh sketches') }}</button><label v-if="o.action!=='pattern'">{{ label('Профили — в порядке выбора','Profiles in selection order') }}</label><label v-for="(s,i) in sketches.filter(s=>s.closed)" v-show="o.action!=='pattern'" :key="s.id"><input v-model="o.profileIds" :value="s.id" type="checkbox">{{ i+1 }} · {{ s.name }} · {{ s.points.length }}</label><label v-if="o.action!=='loft'">{{ label('Траектория','Path') }}<select v-model="o.pathId"><option value="">{{ label('Прямая по оси','Straight along axis') }}</option><option v-for="(s,i) in sketches.filter(s=>!s.closed)" :key="s.id" :value="s.id">{{ i+1 }} · {{ s.name }}</option></select></label></template>
 <template v-if="!['lighten','texture','union','difference','intersection','loft','sweep'].includes(o.action)"><label>{{ label('Направление XYZ','Direction XYZ') }}<input v-for="(_,i) in o.axis" :key="i" v-model.number="o.axis[i]" type="number" step="0.1"></label><label>{{ label('Опорная точка XYZ','Origin XYZ') }}<input v-for="(_,i) in o.origin" :key="i" v-model.number="o.origin[i]" type="number"></label><button :disabled="!hit" @click="picked">{{ label('Взять выбранную грань','Use picked face') }}</button></template>
 <label v-if="['pattern','draft','joint'].includes(o.action)">{{ label(o.action==='draft'?'Угол, °':o.action==='joint'?'Поворот, ° / ход, мм':'Шаг, мм','Angle / travel / spacing') }}<input v-model.number="o.amount" type="number"></label>
 <label v-if="o.action==='pattern'">{{ label('Количество','Count') }}<input v-model.number="o.count" type="number" min="2" max="100"></label>
 <label v-if="['hole','thread','resize'].includes(o.action)">{{ label(o.action==='resize'?'Размер X':'Диаметр','X size / Diameter') }}<input v-model.number="o.width" type="number" min="0.1"></label>
 <label v-if="['hole','resize'].includes(o.action)">{{ label(o.action==='resize'?'Размер Y':'Глубина выборки','Y size / Counterbore depth') }}<input v-model.number="o.height" type="number" min="0.1"></label>
 <label v-if="['hole','thread','resize'].includes(o.action)">{{ label(o.action==='resize'?'Размер Z':'Глубина / длина','Z size / Depth') }}<input v-model.number="o.depth" type="number" min="0.1"></label>
 <label v-if="o.action==='hole'">{{ label('Диаметр выборки','Counterbore diameter') }}<input v-model.number="o.secondary" type="number" min="0.1"></label><label v-if="o.action==='thread'">{{ label('Шаг резьбы','Thread pitch') }}<input v-model.number="o.pitch" type="number" min="0.1"></label>
 <label v-if="['mirror','align','distribute','hole','thread','joint'].includes(o.action)">{{ label('Режим','Mode') }}<select v-model="o.mode"><template v-if="o.action==='mirror'"><option value="copy">{{ label('Копия','Copy') }}</option><option value="replace">{{ label('Заменить','Replace') }}</option></template><template v-else-if="o.action==='hole'"><option value="plain">{{ label('Обычное','Plain') }}</option><option value="counterbore">{{ label('Цековка','Counterbore') }}</option><option value="countersink">{{ label('Зенковка','Countersink') }}</option></template><template v-else-if="o.action==='thread'"><option value="internal">{{ label('Внутренняя','Internal') }}</option><option value="external">{{ label('Наружная','External') }}</option></template><template v-else-if="o.action==='joint'"><option value="revolute">{{ label('Шарнир','Hinge') }}</option><option value="slider">{{ label('Ползун','Slider') }}</option></template><template v-else><option value="min">Min</option><option value="center">Center</option><option value="max">Max</option></template></select></label>
 <details><summary>STEP · {{ label('Сохранённый AP242 B-rep','Retained AP242 B-rep') }}</summary><button @click="retainedStepExport">{{ label('Экспорт сохранённой модели','Export retained model') }}</button><label>{{ label('Импорт AP242','Import AP242') }}<input type="file" accept=".step,.stp" @change="retainedStepImport"></label><p>{{ label('Авторитетный B-rep сохраняется в хранилище моделей проекта IndexedDB; сетка в исходнике служит только предпросмотром. Независимая семантическая проверка AP242 отображается отдельно и по умолчанию не выполнялась.','The authoritative B-rep is saved in the project IndexedDB model store; the source mesh is preview-only. Independent AP242 semantic conformance is reported separately and defaults to not checked.') }}</p></details>
 <template v-if="o.action==='joint'"><label>Min <input v-model.number="jointMin" type="number">Max <input v-model.number="jointMax" type="number"></label><input v-model.number="o.amount" aria-label="Joint position" type="range" :min="jointMin" :max="jointMax" step="0.1"><button @click="loadJoint">{{ label('Загрузить соединение','Load joint') }}</button><button @click="emit('apply',removeCadJoints(source))">{{ label('Удалить соединения','Remove joints') }}</button><small>{{ label('Ось, положение и пределы сохраняются в исходнике. Изменение геометрии требует новой привязки.','Axis, position and limits are saved in source. Geometry changes require a new reference.') }}</small></template><details><summary>STEP · {{ label('Плоские грани','Faceted BREP') }}</summary><button @click="stepExport">{{ label('Экспорт STEP','Export STEP') }}</button><label>{{ label('Импорт STEP','Import STEP') }}<input type="file" accept=".step,.stp" @change="stepImport"></label><p>{{ label('Только FACETED_BREP. Аналитические поверхности и сборочные экземпляры пока не поддерживаются.','FACETED_BREP only. Analytic surfaces and assembly instances are not supported yet.') }}</p></details><details><summary>{{ label('Проверки и чертежи','Checks and drawings') }}</summary><button :disabled="busy" @click="inspection">{{ label('Пересечения и зазоры','Interference and clearance') }}</button><label>Z {{ label('сечения','section') }}<input v-model.number="sectionZ" type="number"></label><button @click="drawing('svg')">SVG</button><button @click="drawing('pdf')">PDF</button><p>{{ label('Три вида, габариты и сечение. Все рёбра видимы.','Three views, dimensions and section. All edges visible.') }}</p></details>
<NominalTrussPanel v-if="o.action==='lighten'&&o.lightening&&spatialMode" :meshes="meshes" :selection="selection" :source="source" :ready="ready" :locale="locale" :options="o.lightening" :print-settings="printSettings" :preview-epoch="previewEpoch" @preview="fieldPreview"/>
<GcodePanel :meshes="meshes" :selection="selection" :source="source" :ready="ready" :locale="locale"/><footer><button :disabled="busy" @click="calculate()">{{ label('Предпросмотр','Preview') }}</button><button :disabled="busy" @click="calculate(true)">{{ label('Применить','Apply') }}</button><button @click="cancel">{{ label('Отмена','Cancel') }}</button></footer><p v-if="busy" role="status">{{ label('Расчёт…','Computing…') }}</p><p v-if="error" role="alert">{{ error }}</p><p v-if="info">{{ info }}</p>
 </aside></template>
<style scoped>.cad-workbench{position:absolute;left:10px;top:100px;z-index:7;width:330px;max-height:65%;overflow:auto;padding:10px;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:6px;font-size:12px}.cad-workbench header,.cad-workbench footer,.cad-workbench label{display:flex;align-items:center;gap:6px;margin:6px 0}.cad-workbench header{justify-content:space-between}.cad-workbench input[type=number]{width:55px}.cad-workbench button,.cad-workbench input,.cad-workbench select{font:inherit;background:var(--surface-raised);color:var(--text);border:1px solid var(--border);padding:5px;border-radius:4px}.cad-workbench select{min-width:0;max-width:240px}.cad-workbench [role=alert]{color:var(--danger)}</style>
